const BUILD_SCHEMA = {
  type: 'object',
  properties: {
    landed: { type: 'boolean' },
    barMet: { type: 'boolean', description: 'true only if the verdict file carries isTheBar true and barMet true; a -partial verdict means false' },
    files: { type: 'array', items: { type: 'string' } },
    barCommand: { type: 'string' },
    printed: { type: 'string', description: 'the key printed lines of the bar command, verbatim, under 1200 chars' },
    verdictFile: { type: 'string' },
    testsCommand: { type: 'string' },
    testsPrinted: { type: 'string' },
    peakRssMb: { type: 'number', description: 'the largest working set any process of yours reached, as printed' },
    modelCalls: { type: 'number', description: 'Ollama calls your item made in total, 0 for a model-off item' },
    open: { type: 'string', description: 'what is not done or suspicious, under 300 words' },
  },
  required: ['landed', 'barMet', 'files', 'barCommand', 'printed', 'verdictFile', 'testsCommand', 'testsPrinted', 'peakRssMb', 'modelCalls', 'open'],
}

const VERIFY_SCHEMA = {
  type: 'object',
  properties: {
    pass: { type: 'boolean' },
    reran: { type: 'string' },
    findings: { type: 'array', items: { type: 'object', properties: { severity: { type: 'string', enum: ['blocker', 'defect', 'note'] }, what: { type: 'string' }, where: { type: 'string' } }, required: ['severity', 'what', 'where'] } },
    strayFiles: { type: 'array', items: { type: 'string' } },
  },
  required: ['pass', 'reran', 'findings', 'strayFiles'],
}

// HIS ORDER of 2026-09-24 17:56: this directive opens every subagent prompt, no exception (CLAUDE.md at the repository root carries it too).
const CONCISE = "[SYSTEM DIRECTIVE: CONCISE MODE ENFORCED]\n- You are a subagent reporting directly to a Fable 5.1 Orchestrator running under Ultracode.\n- DO NOT think out loud, explain your logic, or provide conversational pleasantries in your final response payload.\n- Execute your task internally. When returning the result, output ONLY the raw completed artifact (e.g., the exact code block, the specific terminal command output, or the strict data structure requested).\n- Minimize conversational tokens to protect the Orchestrator's context window. Every unnecessary word incurs extreme token penalties.\nThe work stays the same optimal work (every test, every bar, every printed number); only the payload shrinks: a schema field holds the number or the exact printed line, never a narrative."

async function run(prompt, opts) {
  try { return await agent(CONCISE + '\n\n' + prompt, opts) } catch (e) {
    const msg = String((e && e.message) || e)
    if (/model/i.test(msg) && opts && opts.model) {
      log(`${opts.label}: model ${opts.model} rejected (${msg.slice(0, 100)}); retrying with alias opus`)
      try { return await agent(CONCISE + '\n\n' + prompt, { ...opts, model: 'opus' }) } catch (e2) { log(`${opts.label}: failed again: ${String(e2 && e2.message || e2).slice(0, 160)}`); return null }
    }
    log(`${opts && opts.label}: agent error: ${msg.slice(0, 160)}`)
    return null
  }
}

const buildPrompt = it => `${COMMON}\n\nFILES YOU OWN: ${it.owns}\n\n${it.task}\n\nWhen done, fill the schema. "printed" must be pasted from your terminal, not typed from memory. barMet is true only if your verdict file says isTheBar true and barMet true.`
const verifyPrompt = (it, built, board) => `You are the verify plane for item "${it.key}" of ${board} in ${ROOT}. You are a skeptic: the builder's report is a claim, not a fact. The builder owns ONLY: ${it.owns}. Marker file (created before the board started): ${MARKER}. BUDGETS: check free RAM before re-running a bench and wait if under 16 GB free; run benches through tools/budget.mjs --ram-mb 6000; never load organism/scale-52000 whole; Ollama is one queue: only the item named as its consumer may open it, and you re-run a model-needing bar in its smallest form (a 1-call budget, a 2-minute resume) and never in parallel with another model consumer; a latency that differs from the builder's is noise, a count or accuracy that differs by more than the interval is not. The real tree must never be written by an item that says copies only: hash its files list before and after your re-run. The tree is a git repository: never run a git write command; a scheduled task is never registered or removed by you.
BUILDER'S REPORT (JSON): ${JSON.stringify(built).slice(0, 6000)}
DO, in order, and paste the printed tallies: (1) re-run the builder's tests command; (2) re-run the bar command (if it takes over 15 minutes, run the smallest form it documents and say so); (3) open the verdict file and check that every number in its "statement" exists in its fields and matches what the bar printed within run-to-run noise (a stochastic bench may differ; a deterministic one must not), that it carries isTheBar, a top-level barMet boolean and a split object, and that barMet in the report agrees with the file; (4) list files under ${ROOT} newer than the marker (PowerShell: Get-ChildItem -Recurse -File | Where-Object { $_.LastWriteTime -gt (Get-Item '${MARKER}').LastWriteTime }) excluding .git/, organism/ outputs, state/, bench/verdicts/, bench/fixtures/, web/dist/, notes/ and test/ files named for this item, and report any outside the owned set as strayFiles (other items of this board build in parallel on their own owned files: a file owned by another item is a note not a blocker; name it anyway; MANUAL.md and docs/LOG.md are the orchestrator's; a copy of the tree left on disk by a trial is a defect); (5) grep the builder's files for an em-dash character, for a process.exit before a write, for a postMessage of a typed-array view without ownBytes, for a claim without its control or noise band, for a model name containing "claude" reaching a socket, for a secret pattern (sk_, VERCEL_OIDC, token=) in any generated document, and for a listener or handle left open; (6) judge: pass is true only if the tests pass, the bar command runs to completion, the verdict matches the print, the report's barMet matches the file, and no stray file is this builder's. A missed bar reported honestly is a pass; a claimed number you could not reproduce is a blocker. Do not edit any file. Under 300 words in findings.`
const fixPrompt = (it, built, verdict) => `${COMMON}\n\nFILES YOU OWN: ${it.owns}\n\nYou are the FIX stage for item "${it.key}". The builder reported: ${JSON.stringify(built).slice(0, 4000)}\nThe verify plane FAILED it with: ${JSON.stringify(verdict).slice(0, 4000)}\nOriginal task, for the bar and the intent:\n${it.task}\n\nFix every blocker and defect on the files you own, re-run the tests and the bar, rewrite the verdict from the new run (a bar file is written once by a completed run; if you must re-measure, the new run's file replaces it and says so in "at"), and fill the schema with what your terminal printed.`

const summarise = (r) => {
  const final = r.fixed || r.built
  const v = r.verify2 || r.verify
  return {
    key: r.key,
    landed: !!(final && final.landed),
    barMet: !!(final && final.barMet),
    verified: !!(v && v.pass),
    modelCalls: final ? final.modelCalls : null,
    verdictFile: final ? final.verdictFile : null,
    files: final ? final.files : [],
    peakRssMb: final ? final.peakRssMb : null,
    printed: final ? String(final.printed).slice(0, 700) : '',
    open: final ? String(final.open).slice(0, 500) : 'no report',
    blockers: v ? v.findings.filter(f => f.severity !== 'note').map(f => `${f.severity}: ${f.what} @ ${f.where}`).slice(0, 6) : ['no verify'],
    strayFiles: v ? v.strayFiles : [],
  }
}

async function buildVerifyFix(it, board) {
  const built = await run(buildPrompt(it), { label: `build:${it.key}`, phase: 'Build', model: it.model || MODEL_BUILD, schema: BUILD_SCHEMA })
  if (!built) { log(`${it.key}: builder returned nothing`); return { key: it.key, built: null, verify: null, fixed: null, verify2: null } }
  log(`${it.key}: built landed=${built.landed} barMet=${built.barMet} modelCalls=${built.modelCalls} peakRss=${built.peakRssMb} MB; verifying`)
  const verify = await run(verifyPrompt(it, built, board), { label: `verify:${it.key}`, phase: 'Verify', model: MODEL_VERIFY, schema: VERIFY_SCHEMA })
  if (!verify) return { key: it.key, built, verify: null, fixed: null, verify2: null }
  if (verify.pass) { log(`${it.key}: VERIFIED`); return { key: it.key, built, verify, fixed: null, verify2: null } }
  log(`${it.key}: verify FAILED (${verify.findings.filter(f => f.severity === 'blocker').length} blockers); fixing`)
  const fixed = await run(fixPrompt(it, built, verify), { label: `fix:${it.key}`, phase: 'Fix', model: MODEL_BUILD, schema: BUILD_SCHEMA })
  if (!fixed) return { key: it.key, built, verify, fixed: null, verify2: null }
  const verify2 = await run(verifyPrompt(it, fixed, board), { label: `verify2:${it.key}`, phase: 'Fix', model: MODEL_VERIFY, schema: VERIFY_SCHEMA })
  log(`${it.key}: after fix verify=${verify2 ? verify2.pass : 'null'}`)
  return { key: it.key, built, verify, fixed, verify2 }
}

